INSERT INTO home (
    user_id, addr1, addr2, residence_type, lease_type,
    deposit_price, monthly_rent, maintenance_fee, home_status,
    view_cnt, like_cnt, chat_cnt, room_cnt, supply_area, exclusive_area
) VALUES (
             #{userId}, #{addr1}, #{addr2}, #{residenceType}, #{leaseType},
             #{depositPrice}, #{monthlyRent}, #{maintenaceFee}, #{homeStatus},
             #{viewCnt}, #{likeCnt}, #{chatCnt}, #{roomCnt}, #{supplyArea}, #{exclusiveArea}
         )

INSERT INTO home_detail (
    home_id, build_date, home_floor, building_total_floors,
    home_direction, bathroom_count, is_pet, is_parking_available,area,land_category

) VALUES (
             #{homeId}, #{buildDate}, #{homeFloor}, #{buildingTotalFloors},
             #{homeDirection}, #{bathroomCnt}, #{isPet}, #{isParking}, #{area}, #{landCategory}
         )

mapper.select:
SELECT
h.home_id as homeId, h.user_id as userId, h.addr1, h.addr2,
h.residence_type as residenceType, h.lease_type as leaseType,
h.deposit_price as depositPrice, h.monthly_rent as monthlyRent,
h.maintenance_fee as maintenaceFee, h.home_status as homeStatus,
h.view_cnt as viewCnt, h.like_cnt as likeCnt, h.chat_cnt as chatCnt,
h.room_cnt as roomCnt, h.supply_area as supplyArea, h.exclusive_area as exclusiveArea,
h.created_at as createdAt, h.updated_at as updatedAt,
hd.home_floor as homeFloor, hd.building_total_floors as buildingTotalFloors
FROM home h
LEFT JOIN home_detail hd ON h.home_id = hd.home_id

    h.home_status = 'AVAILABLE'

        AND h.residence_type = #{search.residenceType}


        AND h.lease_type = #{search.leaseType}


        AND h.addr1 LIKE CONCAT('%', #{search.addr1}, '%')


        AND h.deposit_price <= #{search.maxDepositPrice}


        AND h.monthly_rent <= #{search.maxMonthlyRent}


        AND h.maintenance_fee <= #{search.maxMaintenanceFee}


        AND h.supply_area >= #{search.minSupplyArea}


        AND h.supply_area <= #{search.maxSupplyArea}


        AND h.room_cnt >= #{search.minRoomCnt}


        AND h.room_cnt <= #{search.maxRoomCnt}


        AND h.exclusive_area= #{search.exclusiveArea}


        AND hd.home_direction = #{search.homeDirection}


        AND hd.home_floor = #{search.homeFloor}


        AND hd.home_floor >= #{search.minFloor}


        AND hd.home_floor <= #{search.maxFloor}


        AND hd.is_pet = #{search.isPet}


        AND hd.is_parking_available = #{search.isParking}




        ORDER BY

            h.deposit_price, h.monthly_rent


            h.view_cnt


            h.like_cnt


            h.created_at


            DESC


            ASC



        ORDER BY h.created_at DESC


LIMIT #{search.size} OFFSET #{search.offset}

SELECT image_id as imageId, home_id as homeId, image_url as imageUrl
FROM home_image
WHERE home_id = #{homeId}

SELECT COUNT(*)
FROM home_like
WHERE user_id = #{userId} AND home_id = #{homeId}

